package gitrepo_test

import (
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// gitInvocationMarkers identify a line that shells out to git, as opposed to
// the ~90 unrelated Go lines that merely contain the string "status" (JSON
// field tags, agent stream subtypes, the agent-help classification table).
var gitInvocationMarkers = []string{
	`"git"`,          // exec.Command("git", ...) and runner.RunInDir(..., "git", ...)
	"runGit",         // review's thin wrapper
	"gitexec",        // the shared git exec helper
	"RunInDir",       // bootstrapRunner
	"CommandContext", // any remaining direct spawn on the same line
}

// TestGitStatusCallSitesPassNoOptionalLocks fails the build on any `git status`
// invocation that omits --no-optional-locks.
//
// `git status` is a WRITE: it refreshes the index's stat cache and, when
// anything is stale, takes .git/index.lock for the whole worktree walk and
// renames a fresh index over .git/index. Entire only ever wants the porcelain
// output, so that write is pure collateral — and it cost a user a commit that
// deleted every tracked file (issue #2111). See the "`git status` Is a Write"
// section of CLAUDE.md for the full chain.
//
// This is a source-level guard rather than a comment on purpose. The exact same
// producer was diagnosed once before (ENT-242, Feb 2026), the fix was closed
// unmerged on the false premise that `git status --porcelain -z` "reads without
// rewriting", and the knowledge left the codebase entirely.
//
// Limitation: the check is per-line, so an invocation that gofmt wraps across
// several lines could carry the flag on a different line than "status" and read
// as a violation. That direction is safe — it fails loudly and the fix is to
// keep the argv on one line or add the flag beside "status".
func TestGitStatusCallSitesPassNoOptionalLocks(t *testing.T) {
	t.Parallel()

	root := strings.TrimSpace(testutil.RunGit(t, "", "rev-parse", "--show-toplevel"))

	// git grep exits non-zero on zero matches, so RunGit failing here means
	// "found nothing", which cannot be right — see the checked == 0 guard below.
	out := testutil.RunGit(t, root, "grep", "-n", "--", `"status"`, "--", "cmd", "internal")

	var checked int
	for line := range strings.SplitSeq(strings.TrimSpace(out), "\n") {
		path, rest, ok := strings.Cut(line, ":")
		if !ok || !strings.HasSuffix(path, ".go") {
			continue
		}
		// Test files and fixtures may assert on the unguarded argv shape.
		if strings.HasSuffix(path, "_test.go") || strings.Contains(path, "/testutil/") {
			continue
		}
		if !containsAnyMarker(rest) {
			continue // not a git invocation
		}
		checked++
		if strings.Contains(rest, `"--no-optional-locks"`) {
			continue
		}
		t.Errorf("git status invocation without --no-optional-locks:\n  %s\n"+
			"`git status` rewrites the user's .git/index (issue #2111). Add "+
			`"--no-optional-locks" before "status", and set `+
			"cmd.Env = gitrepo.EnvWithoutRepoOverrides() if the call can run "+
			"inside a git hook.", line)
	}

	// If a refactor moves every call site behind a helper this pattern no longer
	// recognises, the guard would silently pass forever. Fail instead so someone
	// re-points it.
	if checked == 0 {
		t.Error("guard matched no git status invocations at all; the detection " +
			"pattern has gone stale and must be re-pointed (gitInvocationMarkers)")
	}
}

func containsAnyMarker(line string) bool {
	for _, m := range gitInvocationMarkers {
		if strings.Contains(line, m) {
			return true
		}
	}
	return false
}

package cli

import (
	"os/exec"
	"path"
	"slices"
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/gitrepo"
	"github.com/stretchr/testify/require"
)

// TestAllHookConfigRelPaths_CoversEveryWorktreeConfigAgent fails the build when
// an agent opens a hook-config file without also declaring where it lives.
//
// A source-level guard rather than a comment, because the omission is invisible
// at the call site: the agent works, its hooks install, and the only thing that
// silently loses coverage is doctor's symlink diagnosis — which reports nothing
// rather than reporting a problem, so no one finds out. Pi and OpenCode nest
// their config below the directory ProtectedDirs names, and the levels in
// between went unchecked exactly this way.
//
// It runs in package cli because that is where every agent's init() has run and
// the registry is fully populated.
func TestAllHookConfigRelPaths_CoversEveryWorktreeConfigAgent(t *testing.T) {
	t.Parallel()

	// Both subprocesses run with git's repo selectors scrubbed. They inherit the
	// environment, and GIT_DIR / GIT_WORK_TREE take precedence over both the
	// working directory and grep.Dir — so a `go test` launched from anywhere
	// that exports them (a `git rebase --exec`, a hook, this CLI's own test
	// harnesses) resolved some other repository entirely. Measured against a
	// decoy repo, the unscrubbed version fails with "no agent calls
	// agent.OpenHookConfig", which is a guard failing for a reason that has
	// nothing to do with what it guards; a decoy that happened to contain
	// matching paths would instead have it pass having checked nothing.
	topLevel := exec.Command("git", "rev-parse", "--show-toplevel") //nolint:noctx // guard test, no cancellation needed
	topLevel.Env = gitrepo.EnvWithoutRepoOverrides()
	repoRoot, err := topLevel.Output()
	if err != nil {
		t.Skipf("not in a git checkout: %v", err)
	}

	dir := strings.TrimSpace(string(repoRoot))
	callers := agentPackagesMatching(t, dir, "agent.OpenHookConfig(")
	locators := agentPackagesMatching(t, dir, ") HookConfigRelPath() string {")

	// Sets, not counts. len(declared) == len(callers) passed whenever an added
	// omission was offset by a removal in the same change — the failure this
	// test exists to catch, since the agent still works and only doctor's
	// diagnosis goes quiet — and failed on an agent whose call happens to sit in
	// a sub-package, which is no defect at all. Both sides are package
	// directories, so they are directly comparable.
	require.Equal(t, locators, callers,
		"the agent packages calling agent.OpenHookConfig and those implementing\n"+
			"agent.HookConfigRelPath must be the same set. An agent that opens its\n"+
			"hook config without declaring where it lives leaves the directories\n"+
			"Entire creates between its own directory and that file unchecked by\n"+
			"doctor's symlink diagnosis.")

	// The registry is the thing doctor actually reads, so a locator that exists
	// in source but never reaches AllHookConfigRelPaths (an agent left out of
	// the registry, or one returning "") is its own failure.
	//
	// A count, deliberately, directly under the argument against counts above —
	// and defeatable the same way, by dropping one agent from the registry while
	// adding another locator. A set comparison would need to map a package
	// directory to the rel path it declares, and nothing does: `geminicli`
	// declares `.gemini/settings.json` and `copilotcli` declares
	// `.github/hooks/entire.json`, so neither the package name nor the path's
	// first component derives the other. The set comparison above is the guard
	// that matters; this one only catches a locator the registry never sees.
	require.Len(t, agent.AllHookConfigRelPaths(), len(locators),
		"%d agent packages implement HookConfigRelPath but the registry reports %d paths (%s)",
		len(locators), len(agent.AllHookConfigRelPaths()), strings.Join(agent.AllHookConfigRelPaths(), ", "))
}

// agentPackagesMatching returns the sorted, deduplicated agent package
// directories whose non-test sources contain needle, asserting that the pattern
// still matches something — a re-worded signature would otherwise turn this
// guard into a comparison of two empty sets.
func agentPackagesMatching(t *testing.T, repoRoot, needle string) []string {
	t.Helper()
	grep := exec.Command("git", "grep", "-l", "--fixed-strings", "--", //nolint:noctx // guard test, no cancellation needed
		needle, "--", ":(glob)cmd/entire/cli/agent/**/*.go")
	grep.Dir = repoRoot
	// Set for the same reason every git subprocess naming its target with
	// cmd.Dir does: git exports GIT_DIR/GIT_WORK_TREE to hooks, and those take
	// precedence over cmd.Dir.
	grep.Env = gitrepo.EnvWithoutRepoOverrides()
	out, err := grep.Output()
	require.NoError(t, err, "no agent source matches %q, which cannot be right", needle)

	var pkgs []string
	for line := range strings.SplitSeq(strings.TrimSpace(string(out)), "\n") {
		if line == "" || strings.HasSuffix(line, "_test.go") {
			continue
		}
		if dir := path.Dir(line); !slices.Contains(pkgs, dir) {
			pkgs = append(pkgs, dir)
		}
	}
	slices.Sort(pkgs)
	require.NotEmpty(t, pkgs, "the detection pattern %q has gone stale and must be re-pointed", needle)
	return pkgs
}

